func SyncCrdsAndUpdateKymaAnnotations(ctx context.Context, kyma *v1beta2.Kyma,
	runtimeClient Client, controlPlaneClient Client) (bool, error) {
	kymaCrdUpdated, err := syncCrdAndUpdateKymaAnnotations(ctx, kyma, runtimeClient, controlPlaneClient,
		v1beta2.KymaKind.Plural())
	if err != nil {
		return false, err
	}

	moduleTemplateCrdUpdated, err := syncCrdAndUpdateKymaAnnotations(ctx, kyma, runtimeClient, controlPlaneClient,
		v1beta2.ModuleTemplateKind.Plural())
	if err != nil {
		return false, err
	}

	return kymaCrdUpdated || moduleTemplateCrdUpdated, nil
}

func syncCrdAndUpdateKymaAnnotations(ctx context.Context, kyma *v1beta2.Kyma,
	runtimeClient Client, controlPlaneClient Client, plural string) (bool, error) {
	kcpCrd, skrCrd, err := fetchCrds(ctx, controlPlaneClient, runtimeClient, plural)
	if err != nil {
		return false, err
	}
	crdUpdated, err := updateRemoteCRD(ctx, kyma, runtimeClient, skrCrd, kcpCrd)
	if err != nil {
		return false, err
	}
	if crdUpdated {
		err = runtimeClient.Get(
			ctx, client.ObjectKey{
				Name: fmt.Sprintf("%s.%s", plural, v1beta2.GroupVersion.Group),
			}, skrCrd,
		)
		if err != nil {
			return false, err
		}
		updateKymaAnnotations(kyma, kcpCrd, KCP)
		updateKymaAnnotations(kyma, skrCrd, SKR)
	}

	return crdUpdated, nil
}

